const previousExploreRender=render;
render=function(){previousExploreRender();if(!data)return;const rs=[1,2,3,4,5,8],vals=rs.map(n=>filtered.filter(r=>r.r===n).reduce((s,r)=>s+(r.v||0),0));let total=0;const totals=vals.map(v=>total+=v),max=Math.max(total,1),x=i=>65+i*80,y=v=>215-180*v/max;let svg='<svg viewBox="0 0 570 260" role="img" aria-label="Lances por rodada em colunas e acumulado em linha">';rs.forEach((n,i)=>{svg+=`<rect x="${x(i)}" y="${y(vals[i])}" width="38" height="${Math.max(1,215-y(vals[i]))}" fill="#1351b4" rx="3"><title>${n}ª rodada: ${money(vals[i])}; acumulado ${money(totals[i])}</title></rect><text x="${x(i)+19}" y="242" text-anchor="middle">${n}ª</text>`});svg+=`<polyline points="${totals.map((v,i)=>(x(i)+19)+','+y(v)).join(' ')}" fill="none" stroke="#168821" stroke-width="3"/>`;svg+='</svg>';$('roundbars').innerHTML='<div class="time-legend"><span><i></i>Lances da rodada</span><span><i class="line-key"></i>Acumulado na seleção</span></div><div class="chart">'+svg+'</div><p class="caption">Lances nominais, não pagamentos. 6ª e 7ª não têm valores comerciais comparáveis.</p>'};
document.querySelector('[data-view="explore"]').click();
